INSERT INTO t0(c0, c1) SELECT x, x * 7 % 13 FROM (WITH RECURSIVE s(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM s WHERE x < 1034) SELECT x FROM s);
SELECT length('café'), upper('café'), lower('café'), substr('café', -2, 4), instr('café', 'pi'), replace('café', 'é', ''), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%é%', 'café' GLOB 'a*', char(87, 943), 'café' || 'pi', 'café' < 'pi', 'café' = 'pi' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', 3, 2), instr('kappa', 'psi'), replace('kappa', 'e', 'XY'), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE 'A%', 'kappa' GLOB '*', char(66, 237), 'kappa' || 'psi', 'kappa' < 'psi', 'kappa' = 'psi' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', -3, 5), instr('xi', 'x_y'), replace('xi', 'a', ''), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE 'A%', 'xi' GLOB '?', char(66, 354), 'xi' || 'x_y', 'xi' < 'x_y', 'xi' = 'x_y' COLLATE NOCASE;
SELECT length('über'), upper('über'), lower('über'), substr('über', 4, 5), instr('über', 'café'), replace('über', 'é', ''), trim('über'), ltrim('über', 'ab'), hex('über'), quote('über'), unicode('über'), 'über' LIKE '%a_', 'über' GLOB '*[a-m]*', char(69, 817), 'über' || 'café', 'über' < 'café', 'über' = 'café' COLLATE NOCASE;
SELECT id, c1, NOT (0 - c2) IN (iif(nullif(c2, c2), -(c1), 'beta'), 'it''s', -0.0) FROM t1 ORDER BY id, c0, c1 DESC, c2;
SELECT nullif(NOT 0, -(x'' IN ('upsilon', x'57208f65e78c', NULL))), (typeof(-1) = CASE WHEN nullif(-934.3, -2) THEN 'alpha' ELSE NULL END);
SELECT a.id, b.id, a.c0, b.c0 FROM t1 a LEFT OUTER JOIN t1 b ON a.id < b.id ORDER BY 1, 2 LIMIT 59;
SELECT count(*) FROM t1 a JOIN t1 b USING(id);
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t1.id) FROM t1 ORDER BY c2 DESC, id;
SELECT id FROM t1 WHERE id NOT IN (SELECT id FROM t1 WHERE iif(c0, id, -593)) ORDER BY id;
SELECT id FROM t1 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 3) ORDER BY id;
SELECT c1 FROM t1 EXCEPT SELECT c2 FROM t1 ORDER BY 1 LIMIT 14 OFFSET 0;
